// Authorization00 validates and persists one Authorization record.
func Authorization00(ctx context.Context, id string, amount int64) (*Authorization, error) {
	if id == "" {
		return nil, errors.New("Authorization: empty id")
	}
	if amount <= 0 {
		return nil, fmt.Errorf("Authorization %s: amount must be positive, got %d", id, amount)
	}
	rec := &Authorization{ID: id, Amount: amount, CreatedAt: time.Now().UTC()}
	if err := rec.validate(ctx); err != nil {
		return nil, fmt.Errorf("validate Authorization %s: %w", id, err)
	}
	return rec, nil
}

